# Description: Sublayer::Action responsible for sending an email via SendGrid.
# It allows sending notifications, alerts, or reports generated by AI processes.
#
# Requires: `sendgrid-ruby` gem
# $ gem install sendgrid-ruby
# Or add `gem 'sendgrid-ruby'` to your Gemfile
#
# It is initialized with a subject, recipient, and body.
# It returns the HTTP response code to confirm the message was sent successfully.
#
# Example usage: When you want to send a notification or update from an AI process via email.

require 'sendgrid-ruby'
include SendGrid

class SendgridSendEmailAction < Sublayer::Actions::Base
  def initialize(subject:, recipient:, body:)
    @subject = subject
    @recipient = recipient
    @body = body
    @api_key = ENV['SENDGRID_API_KEY']
  end

  def call
    from = Email.new(email: 'noreply@example.com') # Replace with your verified SendGrid email
    to = Email.new(email: @recipient)
    content = Content.new(type: 'text/plain', value: @body)
    mail = Mail.new(from, @subject, to, content)

    sg = SendGrid::API.new(api_key: @api_key)
    begin
      response = sg.client.mail._('send').post(request_body: mail.to_json)
      Sublayer.configuration.logger.log(:info, "Email sent successfully to #{@recipient}")
      response.status_code.to_i
    rescue StandardError => e
      Sublayer.configuration.logger.log(:error, "Error sending SendGrid email: #{e.message}")
      raise StandardError, "Failed to send email via SendGrid: #{e.message}"
    end
  end
end
